 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with candidates as (
 select c.clue,p.phrase from unnest(clues)c(clue)
 cross join lateral (values(guess||' '||c.clue),(c.clue||' '||guess))p(phrase)
 where not known ? c.clue and length(p.phrase)<=100
 and exists(select 1 from ascent_game.wordnet_members m where m.word=p.phrase)
 and not exists(select 1 from ascent_game.rejected_associations r where (r.clue=c.clue and r.word=guess) or (r.word=c.clue and r.clue=guess))
), closed as (
 select c.clue, v.a||v.b phrase from unnest(clues)c(clue)
 join (values ('brain','storm'),('book','worm'),('green','room'),('news','paper'),('rain','bow'),('butter','fly'),('moon','light'),('sun','flower'),('tooth','brush'),('snow','flake'),('head','phone'),('foot','ball'),('door','bell'),('fire','fly'),('water','fall'),('light','house'),('day','dream'),('night','mare'),('heart','beat'),('sea','horse'),('hair','pin'),('key','board'),('cup','cake'),('sand','castle'),('wall','paper'),('finger','print'),('eye','brow'),('hand','shake'),('sail','boat'),('space','ship'))v(a,b) on (v.a=guess and v.b=c.clue) or (v.b=guess and v.a=c.clue)
 where not known ? c.clue and exists(select 1 from ascent_game.wordnet_members m where m.word=v.a||v.b or m.word=v.a||' '||v.b)
 and not exists(select 1 from ascent_game.rejected_associations r where (r.clue=c.clue and r.word=guess) or (r.word=c.clue and r.clue=guess))
), best as (select distinct on(clue) clue,phrase from (select * from candidates union all select * from closed) all_candidates order by clue,phrase)
select case when guess is null or guess !~ '^[a-z]+( [a-z]+){0,5}$'
 or guess ~ '(^| )(not|unrelated|none|except|without|or)( |$)'
 or guess in ('thing','object','entity','stuff','part','type','kind','group','person','something','anything','everything','activity','action','event','matter','process')
 or ascent_game.is_displayed_clue(clues,guess) then known
 else known||coalesce((select jsonb_object_agg(clue,'Together they form the established expression “'||phrase||'”.') from best),'{}'::jsonb) end
$function$;
